-- SED I1 core schema. Safe to apply repeatedly; PostGIS is the only mandatory extension.
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS fuzzystrmatch;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE need_status AS ENUM ('suspected','confirmed','matched','in_progress','resolved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS area (
 id bigserial PRIMARY KEY, parent_id bigint REFERENCES area(id), area_type text NOT NULL CHECK(area_type IN ('country','state','district','ward','village','other')),
 name text NOT NULL, normalized_name text GENERATED ALWAYS AS (lower(trim(name))) STORED, code text, geom geometry(MultiPolygon,4326), centroid geography(Point,4326), accuracy_level text NOT NULL DEFAULT 'unknown',
 UNIQUE(parent_id,area_type,normalized_name), CHECK(geom IS NULL OR ST_IsValid(geom))
);
CREATE INDEX IF NOT EXISTS area_geom_gix ON area USING gist(geom);
CREATE INDEX IF NOT EXISTS area_centroid_gix ON area USING gist(centroid);
CREATE INDEX IF NOT EXISTS area_name_trgm ON area USING gin(normalized_name gin_trgm_ops);
CREATE TABLE IF NOT EXISTS location (id bigserial PRIMARY KEY, area_id bigint REFERENCES area(id), point geography(Point,4326), address text, accuracy_level text NOT NULL DEFAULT 'unknown', CHECK(point IS NULL OR ST_SRID(point::geometry)=4326));
CREATE INDEX IF NOT EXISTS location_point_gix ON location USING gist(point);
CREATE TABLE IF NOT EXISTS person (id bigserial PRIMARY KEY, pseudonym text NOT NULL UNIQUE, display_name text, encrypted_phone bytea, age_band text, household_size int CHECK(household_size>0), living_alone boolean NOT NULL DEFAULT false, vulnerability_tags text[] NOT NULL DEFAULT '{}', area_id bigint REFERENCES area(id), location_id bigint REFERENCES location(id), last_contact_at timestamptz, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS person_area_idx ON person(area_id) WHERE active;
CREATE TABLE IF NOT EXISTS household (id bigserial PRIMARY KEY, pseudonym text NOT NULL UNIQUE, area_id bigint REFERENCES area(id), location_id bigint REFERENCES location(id), household_size int NOT NULL CHECK(household_size>0), vulnerability_tags text[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS household_member (household_id bigint REFERENCES household(id) ON DELETE CASCADE, person_id bigint REFERENCES person(id) ON DELETE CASCADE, PRIMARY KEY(household_id,person_id));
CREATE TABLE IF NOT EXISTS person_consent (id bigserial PRIMARY KEY, person_id bigint NOT NULL REFERENCES person(id), purpose text NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz, emergency_override_reason text, CHECK(withdrawn_at IS NULL OR withdrawn_at>=granted_at), CHECK((granted_at IS NOT NULL) OR emergency_override_reason IS NOT NULL));
CREATE INDEX IF NOT EXISTS consent_valid_idx ON person_consent(person_id,purpose) WHERE withdrawn_at IS NULL;
CREATE TABLE IF NOT EXISTS ngo (id bigserial PRIMARY KEY, name text NOT NULL, registration_id text UNIQUE, ngo_type text, state text, district text, address text, sectors text[] NOT NULL DEFAULT '{}', encrypted_contact bytea, capacity int NOT NULL DEFAULT 0 CHECK(capacity>=0), operating_hours jsonb NOT NULL DEFAULT '{}', location_id bigint REFERENCES location(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS volunteer (id bigserial PRIMARY KEY, person_name text NOT NULL, pseudonym text NOT NULL UNIQUE, encrypted_contact bytea, home_area_id bigint REFERENCES area(id), location_id bigint REFERENCES location(id), mode text NOT NULL DEFAULT 'walk', verified boolean NOT NULL DEFAULT false, acceptance_rate numeric(5,4) NOT NULL DEFAULT .5 CHECK(acceptance_rate BETWEEN 0 AND 1), completion_rate numeric(5,4) NOT NULL DEFAULT .5 CHECK(completion_rate BETWEEN 0 AND 1), reliability_updated_at timestamptz NOT NULL DEFAULT now(), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS volunteer_skill (volunteer_id bigint REFERENCES volunteer(id) ON DELETE CASCADE, skill text NOT NULL, PRIMARY KEY(volunteer_id,skill));
CREATE TABLE IF NOT EXISTS volunteer_language (volunteer_id bigint REFERENCES volunteer(id) ON DELETE CASCADE, language text NOT NULL, PRIMARY KEY(volunteer_id,language));
CREATE TABLE IF NOT EXISTS volunteer_availability (id bigserial PRIMARY KEY, volunteer_id bigint NOT NULL REFERENCES volunteer(id) ON DELETE CASCADE, during tstzrange NOT NULL, CHECK(NOT isempty(during)));
CREATE TABLE IF NOT EXISTS resource_type (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, category text NOT NULL, unit text NOT NULL, perishable boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS resource (id bigserial PRIMARY KEY, resource_type_id bigint NOT NULL REFERENCES resource_type(id), owner_ngo_id bigint REFERENCES ngo(id), location_id bigint REFERENCES location(id), quantity_total int NOT NULL CHECK(quantity_total>=0), quantity_available int NOT NULL CHECK(quantity_available BETWEEN 0 AND quantity_total), expires_at timestamptz, perishable boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS resource_type_available_idx ON resource(resource_type_id,expires_at) WHERE quantity_available>0;
CREATE TABLE IF NOT EXISTS need_type (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, required_skills text[] NOT NULL DEFAULT '{}', resource_type_id bigint REFERENCES resource_type(id), sla interval NOT NULL DEFAULT interval '24 hours');
CREATE TABLE IF NOT EXISTS need (id bigserial PRIMARY KEY, person_id bigint REFERENCES person(id), household_id bigint REFERENCES household(id), need_type_id bigint NOT NULL REFERENCES need_type(id), area_id bigint REFERENCES area(id), location_id bigint REFERENCES location(id), status need_status NOT NULL DEFAULT 'suspected', score numeric(8,6) NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 1), confidence numeric(8,6) NOT NULL DEFAULT 0 CHECK(confidence BETWEEN 0 AND 1), priority int NOT NULL DEFAULT 1 CHECK(priority BETWEEN 1 AND 100), detected_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), sla_due_at timestamptz, resolved_at timestamptz, CHECK(person_id IS NOT NULL OR household_id IS NOT NULL));
CREATE INDEX IF NOT EXISTS need_open_area_idx ON need(area_id,need_type_id,priority DESC) WHERE status IN ('suspected','confirmed');
CREATE TABLE IF NOT EXISTS need_history (id bigserial PRIMARY KEY, need_id bigint NOT NULL REFERENCES need(id), status need_status NOT NULL, score numeric(8,6) NOT NULL, confidence numeric(8,6) NOT NULL, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE UNIQUE INDEX IF NOT EXISTS need_one_current_history ON need_history(need_id) WHERE valid_to IS NULL;
CREATE TABLE IF NOT EXISTS need_bundle (id bigserial PRIMARY KEY, person_id bigint REFERENCES person(id), household_id bigint REFERENCES household(id), label text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','matched','closed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS need_bundle_item (bundle_id bigint REFERENCES need_bundle(id) ON DELETE CASCADE, need_id bigint UNIQUE REFERENCES need(id), PRIMARY KEY(bundle_id,need_id));
CREATE TABLE IF NOT EXISTS signal_type (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, default_weight numeric(8,5) NOT NULL CHECK(default_weight BETWEEN 0 AND 1), half_life interval NOT NULL CHECK(half_life>interval '0'), source_reliability numeric(5,4) NOT NULL CHECK(source_reliability BETWEEN 0 AND 1));
CREATE TABLE IF NOT EXISTS signal (id bigserial PRIMARY KEY, signal_type_id bigint NOT NULL REFERENCES signal_type(id), person_id bigint REFERENCES person(id), household_id bigint REFERENCES household(id), area_id bigint REFERENCES area(id), occurred_at timestamptz NOT NULL, source text NOT NULL, source_reliability numeric(5,4) CHECK(source_reliability BETWEEN 0 AND 1), payload jsonb NOT NULL DEFAULT '{}', idempotency_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK(person_id IS NOT NULL OR household_id IS NOT NULL OR area_id IS NOT NULL));
CREATE INDEX IF NOT EXISTS signal_person_time_idx ON signal(person_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS signal_area_time_idx ON signal(area_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS need_signal (need_id bigint REFERENCES need(id) ON DELETE CASCADE, signal_id bigint REFERENCES signal(id), contribution numeric(12,8) NOT NULL, PRIMARY KEY(need_id,signal_id));
CREATE TABLE IF NOT EXISTS need_rule (id bigserial PRIMARY KEY, need_type_id bigint NOT NULL REFERENCES need_type(id), signal_type_id bigint REFERENCES signal_type(id), threshold numeric(8,6) NOT NULL CHECK(threshold BETWEEN 0 AND 1), min_signal_count int NOT NULL DEFAULT 1 CHECK(min_signal_count>=1), min_confidence numeric(8,6) NOT NULL DEFAULT .4 CHECK(min_confidence BETWEEN 0 AND 1), version int NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS confidence_calibration (id bigserial PRIMARY KEY, version int NOT NULL UNIQUE, intercept numeric NOT NULL DEFAULT 0, count_weight numeric NOT NULL DEFAULT .25, diversity_weight numeric NOT NULL DEFAULT .25, recency_weight numeric NOT NULL DEFAULT .25, reliability_weight numeric NOT NULL DEFAULT .25, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS match_weights (version int PRIMARY KEY, weights jsonb NOT NULL, fairness_weight numeric NOT NULL DEFAULT .15, expiry_weight numeric NOT NULL DEFAULT .1, active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS match_weights_one_active ON match_weights(active) WHERE active;
CREATE TABLE IF NOT EXISTS match (id bigserial PRIMARY KEY, need_id bigint NOT NULL REFERENCES need(id), volunteer_id bigint REFERENCES volunteer(id), resource_id bigint REFERENCES resource(id), quantity int NOT NULL DEFAULT 0 CHECK(quantity>=0), status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','accepted','rejected','completed','expired','cancelled')), score numeric NOT NULL, score_breakdown jsonb NOT NULL, triggering_signal_ids bigint[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), version int NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS match_alternative (id bigserial PRIMARY KEY, match_id bigint NOT NULL REFERENCES match(id) ON DELETE CASCADE, rank int NOT NULL CHECK(rank>0), volunteer_id bigint REFERENCES volunteer(id), resource_id bigint REFERENCES resource(id), score numeric NOT NULL, reasons jsonb NOT NULL, UNIQUE(match_id,rank));
CREATE TABLE IF NOT EXISTS reservation (id bigserial PRIMARY KEY, match_id bigint NOT NULL REFERENCES match(id), resource_id bigint REFERENCES resource(id), volunteer_id bigint REFERENCES volunteer(id), quantity int NOT NULL DEFAULT 0 CHECK(quantity>=0), status text NOT NULL DEFAULT 'held' CHECK(status IN ('held','committed','released','expired')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reservation_ttl_idx ON reservation(expires_at) WHERE status='held';
CREATE TABLE IF NOT EXISTS assistance_history (id bigserial PRIMARY KEY, match_id bigint NOT NULL REFERENCES match(id), outcome text NOT NULL CHECK(outcome IN ('success','delay','rejected','no_show')), occurred_at timestamptz NOT NULL DEFAULT now(), duration interval);
CREATE TABLE IF NOT EXISTS change_events (id bigserial PRIMARY KEY, table_name text NOT NULL, entity_id bigint NOT NULL, area_id bigint, change_kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, attempts int NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS change_events_pending_idx ON change_events(id) WHERE processed_at IS NULL;
CREATE TABLE IF NOT EXISTS notification_outbox (id bigserial PRIMARY KEY, recipient_kind text NOT NULL, recipient_id bigint NOT NULL, template text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, actor text NOT NULL DEFAULT current_user, action text NOT NULL, entity_type text NOT NULL, entity_id bigint, details jsonb NOT NULL DEFAULT '{}', previous_hash text, row_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS weight_audit (id bigserial PRIMARY KEY, previous_version int REFERENCES match_weights(version), new_version int REFERENCES match_weights(version), rationale text NOT NULL, samples int NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS import_batch (id bigserial PRIMARY KEY, source text NOT NULL, file_name text NOT NULL, file_hash text NOT NULL, status text NOT NULL DEFAULT 'staged', row_count int NOT NULL DEFAULT 0, accepted_count int NOT NULL DEFAULT 0, rejected_count int NOT NULL DEFAULT 0, report jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(source,file_hash));
CREATE TABLE IF NOT EXISTS import_row_error (id bigserial PRIMARY KEY, batch_id bigint NOT NULL REFERENCES import_batch(id), row_number int NOT NULL, column_name text, reason text NOT NULL, raw_value text);
CREATE TABLE IF NOT EXISTS data_provenance (id bigserial PRIMARY KEY, entity_type text NOT NULL, entity_id bigint NOT NULL, source text NOT NULL, batch_id bigint REFERENCES import_batch(id), imported_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity_type,entity_id,source,batch_id));
CREATE TABLE IF NOT EXISTS dedupe_review_queue (id bigserial PRIMARY KEY, entity_type text NOT NULL, left_id bigint NOT NULL, right_id bigint NOT NULL, similarity numeric NOT NULL, reasons jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity_type,left_id,right_id));
CREATE TABLE IF NOT EXISTS stg_record (id bigserial PRIMARY KEY, batch_id bigint NOT NULL REFERENCES import_batch(id), row_number int NOT NULL, source_record jsonb NOT NULL, normalized_record jsonb, status text NOT NULL DEFAULT 'pending', UNIQUE(batch_id,row_number));
CREATE OR REPLACE FUNCTION sed_audit_append() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE prev text; body text; BEGIN SELECT row_hash INTO prev FROM audit_log ORDER BY id DESC LIMIT 1; body := concat_ws('|',NEW.actor,NEW.action,NEW.entity_type,NEW.entity_id,NEW.details::text,coalesce(prev,''),NEW.created_at::text); NEW.previous_hash:=prev; NEW.row_hash:=encode(digest(body,'sha256'),'hex'); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS audit_hash_before_insert ON audit_log;
CREATE TRIGGER audit_hash_before_insert BEFORE INSERT ON audit_log FOR EACH ROW EXECUTE FUNCTION sed_audit_append();
CREATE OR REPLACE FUNCTION verify_audit_chain() RETURNS boolean LANGUAGE plpgsql AS $$ DECLARE r record; prev text:=NULL; body text; expected text; BEGIN FOR r IN SELECT * FROM audit_log ORDER BY id LOOP body:=concat_ws('|',r.actor,r.action,r.entity_type,r.entity_id,r.details::text,coalesce(prev,''),r.created_at::text); expected:=encode(digest(body,'sha256'),'hex'); IF r.previous_hash IS DISTINCT FROM prev OR r.row_hash IS DISTINCT FROM expected THEN RETURN false; END IF; prev:=r.row_hash; END LOOP; RETURN true; END $$;
CREATE OR REPLACE FUNCTION sed_record_need_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO need_history(need_id,status,score,confidence,valid_from) VALUES(NEW.id,NEW.status,NEW.score,NEW.confidence,NEW.updated_at); ELSE IF ROW(OLD.status,OLD.score,OLD.confidence) IS DISTINCT FROM ROW(NEW.status,NEW.score,NEW.confidence) THEN UPDATE need_history SET valid_to=NEW.updated_at WHERE need_id=NEW.id AND valid_to IS NULL; INSERT INTO need_history(need_id,status,score,confidence,valid_from) VALUES(NEW.id,NEW.status,NEW.score,NEW.confidence,NEW.updated_at); END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS need_history_version ON need;
CREATE TRIGGER need_history_version AFTER INSERT OR UPDATE ON need FOR EACH ROW EXECUTE FUNCTION sed_record_need_history();
